{
    internal LegacyHoleWizardTailAuthoringTemplate(string sample, string featureName, uint folderTypeId, ushort streamVersion, int baseLength, ushort strippedFolderCount, string baseSha256, int markerOffset, uint markerValue, int blockLength, string blockBase64, int? type, int? endCondition, string? standard, string? fastenerType, string? fastenerSize, double? thruHoleDiameter, double? thruHoleDepth, double? counterBoreDiameter, double? counterBoreDepth, double? counterSinkDiameter, double? counterSinkAngle, double? threadDiameter, double? threadDepth, int? sketchPointCount)
    {
        Sample=sample; FeatureName=featureName; FolderTypeId=folderTypeId; StreamVersion=streamVersion; BaseLength=baseLength; StrippedFolderCount=strippedFolderCount; BaseSha256=baseSha256;
        MarkerOffset=markerOffset; MarkerValue=markerValue; BlockLength=blockLength; Block=Convert.FromBase64String(blockBase64);
        Type=type; EndCondition=endCondition; Standard=standard; FastenerType=fastenerType; FastenerSize=fastenerSize;
        ThruHoleDiameter=thruHoleDiameter; ThruHoleDepth=thruHoleDepth; CounterBoreDiameter=counterBoreDiameter; CounterBoreDepth=counterBoreDepth;
        CounterSinkDiameter=counterSinkDiameter; CounterSinkAngle=counterSinkAngle; ThreadDiameter=threadDiameter; ThreadDepth=threadDepth; SketchPointCount=sketchPointCount;
    }
    internal string Sample { get; }
    internal string FeatureName { get; }
    internal uint FolderTypeId { get; }
    internal ushort StreamVersion { get; }
    internal int BaseLength { get; }
    internal ushort StrippedFolderCount { get; }
    internal string BaseSha256 { get; }
    internal int MarkerOffset { get; }
    internal uint MarkerValue { get; }
    internal int BlockLength { get; }
    internal byte[] Block { get; }
    internal int? Type { get; }
    internal int? EndCondition { get; }
    internal string? Standard { get; }
    internal string? FastenerType { get; }
    internal string? FastenerSize { get; }
    internal double? ThruHoleDiameter { get; }
    internal double? ThruHoleDepth { get; }
    internal double? CounterBoreDiameter { get; }
    internal double? CounterBoreDepth { get; }
    internal double? CounterSinkDiameter { get; }
    internal double? CounterSinkAngle { get; }
    internal double? ThreadDiameter { get; }
    internal double? ThreadDepth { get; }
    internal int? SketchPointCount { get; }
}

